/**
 * MCP Server for Todoist API Integration
 * Supports: Create tasks, Search tasks, List projects, Mark tasks complete
 */

import {
  McpServer,
  ResourceTemplate,
} from "@modelcontextprotocol/sdk/server/mcp.js";
import {
  StdioServerTransport,
} from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  z,
} from "@modelcontextprotocol/sdk/types.js";
import axios from "axios";
import fs from "fs";
import path from "path";

// Load environment configuration
const loadEnv = () => {
  const envPath = process.env.ENV_FILE || path.join(process.cwd(), ".env");
  const envContent = fs.readFileSync(envPath, "utf-8");
  const result: Record<string, string> = {};
  envContent.split("\n").forEach(line => {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith("#") && "=" in trimmed) {
      const [key, ...valueParts] = trimmed.split("=");
      result[key.trim()] = valueParts.join("=").trim();
    }
  });
  return result;
};

// Load mock data for testing
const loadMockData = () => {
  const mockPath = path.join(process.cwd(), "mock_todoist_data.json");
  if (fs.existsSync(mockPath)) {
    return fs.readFileSync(mockPath, "utf-8");
  }
  return null;
};

// Parse mock data
const parseMockData = (data: string) => {
  try {
    return JSON.parse(data);
  } catch (e) {
    console.error("Error parsing mock data:", e);
    return null;
  }
};

// MCP Server types and schemas
const CreateTaskSchema = z.object({
  content: z.string().min(1),
  project_id: z.string().nullable(),
  priority: z.number().min(1).max(4).nullable(),
  due_date: z.string().nullable(),
  description: z.string().nullable(),
});

const SearchTaskSchema = z.object({
  query: z.string().min(1),
  project_id: z.string().nullable(),
  limit: z.number().int().min(1).max(100).default(50),
});

const ListProjectsSchema = z.object({
  limit: z.number().int().min(1).max(100).default(50),
  favorite_only: z.boolean().default(false),
});

const MarkTaskCompleteSchema = z.object({
  task_id: z.string(),
  completed: z.boolean(),
});

// Todoist Service Layer
class TodoistService {
  private mockData: any = null;
  private isMockMode: boolean = true;
  private apiUrl: string;
  private token: string;

  constructor() {
    const env = loadEnv();
    this.token = env.TODOIST_API_TOKEN || "";
    this.apiUrl = env.TODOIST_BASE_URL || "https://api.todoist.com/rest/v2";
    this.mockData = loadMockData();

